    return _rotation_response(rotation)


@router.post(
    "/authentication-key-rotations/{rotation_id}/retire",
    response_model=AuthenticationKeyRotationResponse,
)
async def retire_authentication_key_rotation(
    rotation_id: str, request: Request, session: DbSession
) -> AuthenticationKeyRotationResponse:
    raw_body = await request.body()
    # The request body is empty, so the signed body_sha256 is the digest of
    # zero bytes, exactly as for a bodyless request. A non-empty body is
    # malformed input rejected before any state change.
    if raw_body:
        raise ProtectedAccessValidationError("body_must_be_empty")
    caller = await _authenticate_protected(
        request, session, raw_body, read=False
    )
    rotation = service.retire_authentication_key_rotation(
        session, rotation_id, caller
    )
    return _rotation_response(rotation)


@router.get(
    "/trust-evaluations",
    response_model=TrustEvaluationResponse,
)
def evaluate_trust(
    request: Request,
    session: DbSession,
    target_type: str | None = Query(default=None),
    target_id: str | None = Query(default=None),
    min_signers: str | None = Query(default=None),
) -> TrustEvaluationResponse:
    # Raw multi-values are inspected deliberately: a repeated scalar is
    # rejected instead of silently taking the last value, and blank or
    # non-numeric values are never coerced to defaults.
    raw = request.query_params

    unknown = set(raw) - _TRUST_EVALUATION_PARAMS
    if unknown:
        # Undeclared parameters are rejected rather than ignored, so a typo
        # (e.g. ``min_signer``) never silently changes the evaluation.
        field = sorted(unknown)[0]
        raise _query_validation_error(
            field, f"unknown query parameter: {field}", "value_error.unknown"
        )

    target_type = _parse_once(raw, "target_type")
    if target_type is None:
        raise _query_validation_error(
            "target_type", "Field required", "value_error.missing"
        )
    if target_type not in ATTESTATION_TARGET_TYPES:
        # Covers missing values, whitespace/blank strings, casing variants,
        # and anything other than the two literal target types.
        raise _query_validation_error(
            "target_type",
            "target_type must be 'claim' or 'evidence_bundle'",
            "value_error",
        )

    target_id = _parse_once(raw, "target_id")
    if target_id is None:
        raise _query_validation_error(
            "target_id", "Field required", "value_error.missing"
        )
    if not target_id.strip():
        # A blank identifier is invalid rather than a lookup of the empty
        # string (which would merely 404).
        raise _query_validation_error(
            "target_id", "target_id must not be empty", "value_error"
        )

    threshold = _parse_int_param(
        raw,
        "min_signers",
        service.DEFAULT_TRUST_MIN_SIGNERS,
        service.MIN_TRUST_MIN_SIGNERS,
        service.MAX_TRUST_MIN_SIGNERS,
    )

    # All parameters are validated before any existence lookup: a malformed
    # request is a 422 even when the target also happens to be missing.
    result = service.evaluate_trust(
        session, target_type, target_id, threshold
    )
    return TrustEvaluationResponse(**result)


_AUDIT_EVENTS_PARAMS = frozenset(
    {"event_type", "resource_id", "from", "to", "limit", "cursor"}
)


def _parse_rfc3339_param(raw, field: str):
    """Parse an optional strict RFC 3339 UTC timestamp query parameter."""
    value = _parse_once(raw, field)
    if value is None:
        return None
    if not value.strip():
        raise _query_validation_error(
            field, f"{field} must not be empty", "value_error"
        )
    parsed = parse_rfc3339_utc(value)
    if parsed is None:
        raise _query_validation_error(
            field,
            f"{field} must be an RFC 3339 UTC timestamp",
            "value_error.datetime",
        )
    return parsed


def _audit_time_claim(dt) -> str | None:
    # The cursor binds the effective instant, not its spelling: equivalent
    # notations ("Z" vs "+00:00") canonicalize to the same claim.
    return dt.isoformat() if dt is not None else None


@router.get("/audit-events", response_model=AuditEventPageResponse)
def list_audit_events(request: Request, session: DbSession) -> AuditEventPageResponse:
    # Raw multi-values are inspected deliberately: a repeated scalar is
    # rejected instead of silently taking the last value, and blank or
    # malformed values are never coerced to defaults.
    raw = request.query_params

    unknown = set(raw) - _AUDIT_EVENTS_PARAMS
    if unknown:
        # Undeclared parameters are rejected rather than ignored, so a typo
        # never silently changes the search.
        field = sorted(unknown)[0]
        raise _query_validation_error(
            field, f"unknown query parameter: {field}", "value_error.unknown"
        )

    event_type = _parse_nonempty_filter(raw, "event_type")
    resource_id = _parse_nonempty_filter(raw, "resource_id")

    from_dt = _parse_rfc3339_param(raw, "from")
    to_dt = _parse_rfc3339_param(raw, "to")
    if from_dt is not None and to_dt is not None and from_dt > to_dt:
        raise _query_validation_error(
            "from",
            "from must not be later than to",
            "value_error.range",
        )

    page_limit = _parse_int_param(
        raw,
        "limit",
        service.DEFAULT_AUDIT_EVENTS_LIMIT,
        service.MIN_AUDIT_EVENTS_LIMIT,
        service.MAX_AUDIT_EVENTS_LIMIT,
    )

    cursor = _parse_once(raw, "cursor")
    offset = 0
    if cursor is not None:
        try:
            claims = pagination.decode_typed_cursor(
                request.app.state.audit_events_cursor_secret,
                pagination.AUDIT_EVENTS_CURSOR,
                cursor,
            )
        except InvalidCursorError as exc:
            raise _query_validation_error(
                "cursor",
                "cursor is malformed, expired, or invalid",
                "value_error.cursor",
            ) from exc
        # The cursor only resumes the query that issued it: every effective
        # filter and the effective limit must match exactly.
        expected = {
            "event_type": event_type,
            "resource_id": resource_id,
            "from": _audit_time_claim(from_dt),
            "to": _audit_time_claim(to_dt),
            "limit": page_limit,
        }
        if any(claims[key] != value for key, value in expected.items()):
            raise _query_validation_error(
                "cursor",
                "cursor does not match the query parameters",
                "value_error.cursor",
            )
        offset = claims["offset"]

    # Strictly read-only: the search writes no resource and no audit event.
    items = service.list_audit_events(
        session, event_type, resource_id, from_dt, to_dt
    )
    total = len(items)

    next_cursor: str | None = None
    if offset >= total:
        # At or past the end of the (stable) result set: the page is empty
        # and no further cursor can be issued.
        page = []
    else:
        page = items[offset : offset + page_limit]
        next_offset = offset + len(page)
        if next_offset < total:
            next_cursor = pagination.encode_typed_cursor(
                request.app.state.audit_events_cursor_secret,
                pagination.AUDIT_EVENTS_CURSOR,
                {
                    "event_type": event_type,
                    "resource_id": resource_id,
                    "from": _audit_time_claim(from_dt),
                    "to": _audit_time_claim(to_dt),
                    "limit": page_limit,
                    "offset": next_offset,
                },
            )

    return AuditEventPageResponse(
        items=[AuditEventItem.model_validate(item) for item in page],
        count=total,
        next_cursor=next_cursor,
    )

"""Versioned, signed, opaque pagination cursors.

A cursor captures the exact position within one filtered result set and
binds to every effective query parameter of the request that produced it.
Cursors are opaque to clients: the payload is JSON wrapped in URL-safe
Base64 and authenticated with HMAC-SHA256 using a server-held secret, so a
cursor cannot be forged or tampered with. Any malformed, unsigned,
wrong-version/kind, or structurally invalid token is rejected by the
caller as a ``422 validation_error`` rather than trusted.

Each cursor family (lineage traversal, a content's evidence-bundle list,
...) defines its own :class:`CursorKind`: a distinct format marker, claim
set, and claim validation. A cursor minted for one family can never resume
another family's query, even though all families share the server secret.
"""

from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import json
from dataclasses import dataclass
from typing import Any, Callable

from provenance.time_utils import parse_rfc3339_utc

#: Legacy lineage cursor format generation. Bump only when the lineage claim
#: set/encoding changes; cursors carrying any other marker are rejected as
#: expired/unknown.
LINEAGE_CURSOR_VERSION = "v1"

#: Marker for cursors that page through one content's evidence bundles.
CONTENT_EVIDENCE_CURSOR_VERSION = "ce1"

#: Marker for cursors that page through the audit-event search.
AUDIT_EVENTS_CURSOR_VERSION = "ae1"


class InvalidCursorError(ValueError):
    """The cursor token is absent, malformed, expired, or unverifiable."""


@dataclass(frozen=True)
class CursorKind:
    """One cursor family: its wire marker, claim fields, and validation."""

    #: First token segment; namespaces the family and its format generation.
    version: str
    #: Claims whose exact values must match the request carrying the cursor,
    #: in stable serialized order. ``offset`` is the position state itself.
    claim_fields: tuple[str, ...]
    #: Raises :class:`InvalidCursorError` for a wrongly-typed/out-of-range
    #: claim of a structurally decoded payload.
    validate: Callable[[dict[str, Any]], None]


def _b64encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64decode(value: str) -> bytes:
    try:
        padding = "=" * (-len(value) % 4)
        return base64.urlsafe_b64decode(value + padding)
    except (binascii.Error, ValueError) as exc:
        raise InvalidCursorError("cursor is not valid base64") from exc


def _sign(secret: bytes, version: str, payload: str) -> bytes:
    return hmac.new(
        secret, f"{version}.{payload}".encode("utf-8"), hashlib.sha256
    ).digest()


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _optional_nonempty_str(claims: dict[str, Any], field: str) -> None:
    value = claims[field]
    if value is not None and (not isinstance(value, str) or not value):
        raise InvalidCursorError(f"cursor {field} is invalid")


def _validate_lineage_claims(claims: dict[str, Any]) -> None:
    if not isinstance(claims["content_id"], str) or not claims["content_id"]:
        raise InvalidCursorError("cursor content_id is invalid")
    if claims["direction"] not in ("ancestors", "descendants"):
        raise InvalidCursorError("cursor direction is invalid")
    if not isinstance(claims["relation_type"], str | None) or (
        isinstance(claims["relation_type"], str)
        and claims["relation_type"] not in ("version_of", "derived_from")
    ):
        raise InvalidCursorError("cursor relation_type is invalid")
    for field in ("max_depth", "min_depth", "limit", "offset"):
        if not _is_int(claims[field]):
            raise InvalidCursorError(f"cursor {field} must be an integer")
    if not (1 <= claims["max_depth"] <= 32):
        raise InvalidCursorError("cursor max_depth is out of range")
    if not (1 <= claims["min_depth"] <= claims["max_depth"]):
        raise InvalidCursorError("cursor min_depth is out of range")
    if not (1 <= claims["limit"] <= 100):
        raise InvalidCursorError("cursor limit is out of range")
    # An offset of 0 is never issued (a first page carries no cursor); a
    # negative offset is structurally invalid. No tight upper bound is
    # imposed: a wide graph can legitimately page past any small constant,
    # and a client cannot forge a large value without the server secret.
    if claims["offset"] < 1:
        raise InvalidCursorError("cursor offset must be a positive integer")


#: Lineage traversal cursor family (kept under the original ``v1`` marker).
LINEAGE_CURSOR = CursorKind(
    version=LINEAGE_CURSOR_VERSION,
    claim_fields=(
        "content_id",
        "direction",
        "max_depth",
        "min_depth",
        "relation_type",
        "limit",
        "offset",
    ),
    validate=_validate_lineage_claims,
)


def _validate_content_evidence_claims(claims: dict[str, Any]) -> None:
    if not isinstance(claims["content_id"], str) or not claims["content_id"]:
        raise InvalidCursorError("cursor content_id is invalid")
    # The exact-match filters are either absent (null) or non-empty strings.
    _optional_nonempty_str(claims, "evidence_type")
    _optional_nonempty_str(claims, "media_type")
    for field in ("limit", "offset"):
        if not _is_int(claims[field]):
            raise InvalidCursorError(f"cursor {field} must be an integer")
    if not (1 <= claims["limit"] <= 100):
        raise InvalidCursorError("cursor limit is out of range")
    if claims["offset"] < 1:
        raise InvalidCursorError("cursor offset must be a positive integer")


#: Cursor family for ``GET /v1/contents/{id}/evidence-bundles``.
CONTENT_EVIDENCE_CURSOR = CursorKind(
    version=CONTENT_EVIDENCE_CURSOR_VERSION,
    claim_fields=(
        "content_id",
        "evidence_type",
        "media_type",
        "limit",
        "offset",
    ),
    validate=_validate_content_evidence_claims,
)


def _validate_audit_events_claims(claims: dict[str, Any]) -> None:
    # The exact-match filters are either absent (null) or non-empty strings.
    _optional_nonempty_str(claims, "event_type")
    _optional_nonempty_str(claims, "resource_id")
    # The time bounds are absent (null) or canonical RFC 3339 UTC strings.
    for field in ("from", "to"):
        value = claims[field]
        if value is not None and (
            not isinstance(value, str) or parse_rfc3339_utc(value) is None
        ):
            raise InvalidCursorError(f"cursor {field} is invalid")
    for field in ("limit", "offset"):
        if not _is_int(claims[field]):
            raise InvalidCursorError(f"cursor {field} must be an integer")
    if not (1 <= claims["limit"] <= 100):
        raise InvalidCursorError("cursor limit is out of range")
    if claims["offset"] < 1:
        raise InvalidCursorError("cursor offset must be a positive integer")


#: Cursor family for ``GET /v1/audit-events``.
AUDIT_EVENTS_CURSOR = CursorKind(
    version=AUDIT_EVENTS_CURSOR_VERSION,
    claim_fields=(
        "event_type",
        "resource_id",
        "from",
        "to",
        "limit",
        "offset",
    ),
    validate=_validate_audit_events_claims,
)


def encode_typed_cursor(
    secret: bytes, kind: CursorKind, claims: dict[str, Any]
) -> str:
    """Return an opaque, signed token for normalized pagination ``claims``."""
    payload = _b64encode(
        json.dumps(
            {field: claims[field] for field in kind.claim_fields},
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    )
    signature = _b64encode(_sign(secret, kind.version, payload))
    return f"{kind.version}.{payload}.{signature}"


def decode_typed_cursor(
    secret: bytes, kind: CursorKind, token: str
) -> dict[str, Any]:
    """Verify and decode ``token``, returning its normalized claims dict.

    Raises :class:`InvalidCursorError` for an empty token, wrong number of
    segments, an unknown family/version marker, bad Base64/JSON, a missing-
    or wrongly-typed claim, an out-of-range offset/limit, or a signature
    that does not authenticate the payload.
    """
    if not isinstance(token, str) or not token:
        raise InvalidCursorError("cursor must not be empty")
    parts = token.split(".")
    if len(parts) != 3:
        raise InvalidCursorError("cursor has an invalid structure")
    version, payload, signature = parts
    if version != kind.version:
        raise InvalidCursorError("cursor uses an unknown or expired version")

    expected_signature = _b64encode(_sign(secret, version, payload))
    if not hmac.compare_digest(signature, expected_signature):
        raise InvalidCursorError("cursor signature is invalid")

    try:
        raw = _b64decode(payload)
        claims = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidCursorError("cursor payload is not valid JSON") from exc

    if not isinstance(claims, dict) or set(claims) != set(kind.claim_fields):
        raise InvalidCursorError("cursor payload has an invalid claim set")
    kind.validate(claims)
    return claims


def encode_cursor(secret: bytes, claims: dict[str, Any]) -> str:
    """Encode a lineage cursor (backward-compatible wrapper)."""
    return encode_typed_cursor(secret, LINEAGE_CURSOR, claims)


def decode_cursor(secret: bytes, token: str) -> dict[str, Any]:
    """Decode a lineage cursor (backward-compatible wrapper)."""
    return decode_typed_cursor(secret, LINEAGE_CURSOR, token)

        "decision": (
            TRUST_DECISION_TRUSTED
            if qualified >= min_signers
            else TRUST_DECISION_UNTRUSTED
        ),
    }


# Audit-event search paging bounds.
DEFAULT_AUDIT_EVENTS_LIMIT = 50
MIN_AUDIT_EVENTS_LIMIT = 1
MAX_AUDIT_EVENTS_LIMIT = 100


def list_audit_events(
    session: Session,
    event_type: str | None = None,
    resource_id: str | None = None,
    from_dt=None,
    to_dt=None,
) -> list[AuditEvent]:
    """Return audit events in stable creation order, optionally filtered.

    ``event_type`` and ``resource_id`` are exact, combinable string matches.
    ``from_dt``/``to_dt`` are timezone-aware UTC instants applied as
    inclusive ``created_at`` bounds. Results follow the events' stable
    creation order (``created_at`` with the monotonic ``seq`` tiebreaker).
    The function is strictly read-only: it writes no resource and no audit
    event.
    """
    stmt = select(AuditEvent)
    if event_type is not None:
        stmt = stmt.where(AuditEvent.event_type == event_type)
    if resource_id is not None:
        stmt = stmt.where(AuditEvent.resource_id == resource_id)
    if from_dt is not None:
        stmt = stmt.where(AuditEvent.created_at >= from_dt)
    if to_dt is not None:
        stmt = stmt.where(AuditEvent.created_at <= to_dt)
    stmt = stmt.order_by(*_AUDIT_EVENT_ORDER)
    return list(session.execute(stmt).scalars().all())


def _require_content(session: Session, content_id: str) -> Content:
    """Return content by id or raise :class:`ContentNotFoundError`."""
    content = session.execute(
        select(Content).where(Content.id == content_id)
    ).scalar_one_or_none()
    if content is None:
